        kind: "And",
        left: { kind: "Text", value: "beta" },
        right: { kind: "Text", value: "gamma" },
      },
      range: range(0, 19),
    });

    expect(parse("alpha AND beta OR gamma")).toMatchObject({
      kind: "Or",
      left: {
        kind: "And",
        left: { kind: "Text", value: "alpha" },
        right: { kind: "Text", value: "beta" },
      },
      right: { kind: "Text", value: "gamma" },
    });
  });

